public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    int maxLen = 0;
    for (String s : strings) {
        if (s != null) {
            maxLen = Math.max(maxLen, s.length());
        }
    }

    if (maxLen == 0) {
        return 0;
    }

    // Collect all substrings of all strings and their inverses
    Set<String> allSubstrings = new HashSet<>();
    for (String s : strings) {
        if (s == null) continue;
        for (int i = 0; i < s.length(); i++) {
            for (int j = i + 1; j <= s.length(); j++) {
                String sub = s.substring(i, j);
                allSubstrings.add(sub);
                // Add inverse (reverse) of the substring
                allSubstrings.add(new StringBuilder(sub).reverse().toString());
            }
        }
    }

    // For each candidate substring, check if it or its inverse appears in every string
    int result = 0;
    for (String candidate : allSubstrings) {
        if (candidate.length() <= result) {
            continue;
        }
        String inverse = new StringBuilder(candidate).reverse().toString();
        boolean foundInAll = true;
        for (String s : strings) {
            if (s == null) {
                foundInAll = false;
                break;
            }
            if (!s.contains(candidate) && !s.contains(inverse)) {
                foundInAll = false;
                break;
            }
        }
        if (foundInAll) {
            result = candidate.length();
        }
    }

    return result;
}

