public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }

    int startX = start[0];
    int startY = start[1];
    int endX = end[0];
    int endY = end[1];

    // Check if start or end are out of bounds
    if (startX < 0 || startX >= n || startY < 0 || startY >= n || endX < 0 || endX >= n || endY < 0 || endY >= n) {
        return "cannot be travelled";
    }

    // If start equals end, travel is possible
    if (startX == endX && startY == endY) {
        return "can be travelled";
    }

    // Build adjacency list
    List<List<int[]>> graph = new ArrayList<>();
    for (int i = 0; i < n * n; i++) {
        graph.add(new ArrayList<>());
    }

    if (paths != null) {
        for (int[] path : paths) {
            if (path == null || path.length < 4) {
                continue;
            }
            int x1 = path[0];
            int y1 = path[1];
            int x2 = path[2];
            int y2 = path[3];

            if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n || x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) {
                continue;
            }

            int node1 = x1 * n + y1;
            int node2 = x2 * n + y2;

            graph.get(node1).add(new int[]{x2, y2});
            graph.get(node2).add(new int[]{x1, y1});
        }
    }

    // BFS to check if end is reachable from start
    boolean[][] visited = new boolean[n][n];
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(new int[]{startX, startY});
    visited[startX][startY] = true;

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        int cx = current[0];
        int cy = current[1];

        if (cx == endX && cy == endY) {
            return "can be travelled";
        }

        int nodeIndex = cx * n + cy;
        for (int[] neighbor : graph.get(nodeIndex)) {
            int nx = neighbor[0];
            int ny = neighbor[1];
            if (!visited[nx][ny]) {
                visited[nx][ny] = true;
                queue.offer(new int[]{nx, ny});
            }
        }
    }

    return "cannot be travelled";
}

