public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        return "appx(null, null) = 0";
    }
    int len1 = word1.length();
    int len2 = word2.length();
    int sumLen = len1 + len2;
    if (sumLen == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }
    int[] freq1 = new int[26];
    int[] freq2 = new int[26];
    for (char c : word1.toCharArray()) {
        if (c >= 'A' && c <= 'Z') {
            freq1[c - 'A']++;
        } else if (c >= 'a' && c <= 'z') {
            freq1[c - 'a']++;
        }
    }
    for (char c : word2.toCharArray()) {
        if (c >= 'A' && c <= 'Z') {
            freq2[c - 'A']++;
        } else if (c >= 'a' && c <= 'z') {
            freq2[c - 'a']++;
        }
    }
    int common = 0;
    for (int i = 0; i < 26; i++) {
        common += Math.min(freq1[i], freq2[i]);
    }
    int numerator = common;
    int denominator = sumLen;
    if (numerator == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }
    int gcd = gcd(numerator, denominator);
    numerator /= gcd;
    denominator /= gcd;
    if (denominator == 1) {
        return "appx(" + word1 + ", " + word2 + ") = " + numerator;
    } else {
        return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
    }
}

