public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }

    int[] count = new int[k];
    for (int num : arr) {
        int remainder = ((num % k) + k) % k;
        count[remainder]++;
    }

    // For remainder 0, count must be even
    if (count[0] % 2 != 0) {
        return false;
    }

    // For each remainder i from 1 to k/2, check if count[i] == count[k-i]
    for (int i = 1; i <= k / 2; i++) {
        if (i == k - i) {
            // This happens when k is even and i = k/2
            if (count[i] % 2 != 0) {
                return false;
            }
        } else {
            if (count[i] != count[k - i]) {
                return false;
            }
        }
    }

    return true;
}

