public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n == 0) {
        return 0;
    }

    // Build adjacency list
    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        graph.get(u).add(v);
        graph.get(v).add(u);
    }

    // DFS to calculate minimum time
    // We need to visit a node if it has an apple or if any of its descendants have an apple
    // The time to visit a node and return is 2 (one edge down, one edge up)
    // We use a visited array to avoid going back to parent

    int[] result = {0};
    dfs(0, -1, graph, hasApple, result);

    return result[0];
}

