public int minOperations(int n) {
    // The array is arr[i] = 2*i + 1 for i in [0, n-1]
    // The target value to make all elements equal is the average of the array.
    // Sum of arr = sum_{i=0}^{n-1} (2*i + 1) = 2 * (n-1)*n/2 + n = n*(n-1) + n = n^2
    // Average = n^2 / n = n
    // So the target value is n.
    // The number of operations is the sum of positive differences (or negative differences) from the target.
    // Since the array is symmetric around the average, we can compute the sum of (target - arr[i]) for i where arr[i] < target.
    // arr[i] = 2*i + 1 < n  =>  2*i + 1 < n  =>  i < (n-1)/2
    // For each such i, the difference is n - (2*i + 1).
    // We sum these differences for i from 0 to floor((n-2)/2) (i.e., while 2*i+1 < n).

    int operations = 0;
    for (int i = 0; i < n; i++) {
        int val = 2 * i + 1;
        if (val < n) {
            operations += (n - val);
        }
    }
    return operations;
}

