public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }

    int ones = 0;
    int twos = 0;

    for (int num : nums) {
        // Update twos: if a bit is already in ones and appears again, move it to twos
        twos |= (ones & num);
        // Update ones: if a bit is in twos, remove it from ones (it has appeared twice)
        ones ^= num;
        // Remove bits that have appeared three times (present in both ones and twos)
        int threes = ones & twos;
        ones &= ~threes;
        twos &= ~threes;
    }

    return ones;
}

